"""This template is filled in memory for the selected Ubuntu computer."""
import json
import pathlib
import shutil
import subprocess
import sys
import tarfile
import tempfile
from urllib.request import ProxyHandler, build_opener

# Built from configure_storage.py by build_storage_bootstrap.py.
STORAGE_SETUP_SOURCE_B64 = ""

bundle_url = __BUNDLE_URL__
complete_url = __COMPLETE_URL__

if not sys.platform.startswith("linux"):
    raise SystemExit("Run this setup on Ubuntu.")
if not shutil.which("systemctl") or not shutil.which("sudo"):
    raise SystemExit("This installer needs Ubuntu with systemd and sudo.")

if "--configure-storage" in sys.argv:
    import base64
    if not STORAGE_SETUP_SOURCE_B64:
        raise SystemExit("The storage update has not been packaged yet.")
    storage_work = pathlib.Path(tempfile.mkdtemp(prefix="lan-messenger-storage-"))
    try:
        script = storage_work / "configure_storage.py"
        script.write_bytes(base64.b64decode(STORAGE_SETUP_SOURCE_B64, validate=True))
        script.chmod(0o600)
        print("Enter your Ubuntu password to move messenger uploads to the selected drive.", flush=True)
        subprocess.run(["sudo", sys.executable, "-B", str(script)], check=True)
    finally:
        try:
            shutil.rmtree(storage_work)
        except OSError:
            print("Temporary update files remain at " + str(storage_work), file=sys.stderr)
    raise SystemExit(0)

opener = build_opener(ProxyHandler({}))
print("Copying the messenger, chat history and attachments from Windows…", flush=True)
print("The Windows messenger will pause new messages during the move.", flush=True)
work = pathlib.Path(tempfile.mkdtemp(prefix="lan-messenger-setup-"))
try:
    with opener.open(bundle_url, timeout=120) as response, tarfile.open(fileobj=response, mode="r|") as archive:
        for member in archive:
            path = pathlib.PurePosixPath(member.name)
            if path.is_absolute() or ".." in path.parts or not path.parts or path.parts[0] != "lan-messenger" or not member.isfile():
                raise ValueError("Unexpected file in the messenger transfer.")
            destination = work.joinpath(*path.parts)
            destination.parent.mkdir(parents=True, exist_ok=True)
            with archive.extractfile(member) as source, destination.open("xb") as output:
                shutil.copyfileobj(source, output, length=65536)
            destination.chmod(0o600)
    app = work / "lan-messenger"
    print("Transfer finished. Enter your Ubuntu password to install and start the service.", flush=True)
    # Root-owned bytecode caches would prevent this user's final cleanup.
    subprocess.run(["sudo", sys.executable, "-B", str(app / "install_ubuntu.py")], check=True)
    try:
        with opener.open(complete_url, timeout=5) as response:
            result = json.load(response)
        print("Migration complete. Open " + result["url"] + " on all computers.")
        print("Windows is no longer needed to host the messenger.")
    except OSError:
        print("Ubuntu is running. The Windows status could not be updated; open the Ubuntu address shown above.")
finally:
    try:
        shutil.rmtree(work)
    except OSError:
        # Cleanup must not replace a successful result or hide an installation error.
        print("Temporary setup files could not be removed from " + str(work) +
              ". The installation result shown above is unchanged.", file=sys.stderr)
